input.command:
sed -i 's/^result.status         #/result.status  #/' README.md
uv run ruff format --check . && uv run ruff check . && uv run ty check
cat > /tmp/t.py <<'EOF'
import threading, http.server
from webhooks.dispatch import deliver, DeliveryError
codes=[500,503,200]
class H(http.server.BaseHTTPRequestHandler):
    def do_POST(s):
        s.send_response(codes.pop(0) if codes else 404); s.end_headers()
    def log_message(*a): pass
srv=http.server.HTTPServer(("127.0.0.1",0),H); threading.Thread(target=srv.serve_forever,daemon=True).start()
u=f"http://127.0.0.1:{srv.server_port}"
r=deliver(u,{},sleep=lambda s:print("sleep",s)); print(r.status,len(r.attempts))
try: deliver(u,{},sleep=lambda s:None)
except DeliveryError as e: print(e,len(e.attempts))
srv.shutdown()
try: deliver(u,{},sleep=lambda s:None)
except DeliveryError as e: print(e,len(e.attempts))
EOF
PYTHONPATH=src uv run python /tmp/t.py

